-- Rollback of migration 010 (performance_rollup), generated by focus.migrations.rollback_script from the forward
-- script's declared objects. Recovery is forward by default; this exists for an install that has just failed review.
-- The runner executes it in one transaction under sp_getapplock('FOCUS_FN_MIGRATIONS'); any guard stops it whole.
-- Nothing here deletes a row.
SET XACT_ABORT ON;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_JobName) THROW 51951, 'WEB_APP.FOCUS_FN_JobName holds rows; recover forward with a new migration', 1;
DROP TABLE WEB_APP.FOCUS_FN_JobName;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_JobOutcome) THROW 51952, 'WEB_APP.FOCUS_FN_JobOutcome holds rows; recover forward with a new migration', 1;
DROP TABLE WEB_APP.FOCUS_FN_JobOutcome;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_TeamShiftPerformance) THROW 51953, 'WEB_APP.FOCUS_FN_TeamShiftPerformance holds rows; recover forward with a new migration', 1;
DROP TABLE WEB_APP.FOCUS_FN_TeamShiftPerformance;
